INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1017, '数学', '三年级', '应用题', 3, '{"stem": "三年级一共有217名学生，准备一起过十岁生日，每盒蛋糕28元（一盒4块）。①每个学生一块蛋糕，学校买55盒够吗？②三（1）班有36人，正好拿9盒，请你估算一下，李老师大约要准备多少元？", "options": null}', '①够：55×4=220（块）>217 块；②大约准备270元：把28看作30，9×30=270（元）', '①55 盒有 55×4=220 块 >217 块 → 够；②每盒 28≈30 元，9×30=270（元）>实际 9×28=252（元）→ 准备 270 元够。', 'paper', '["practice", "ykl3sx", "2.10"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1018, '数学', '三年级', '应用题', 3, '{"stem": "超市促销：一次购物满200元优惠20元；满300元优惠40元。小华的奶奶买了5盒牛肉，每盒牛肉62元，实际要付多少元？", "options": null}', '270元', '5×62=310（元），满 300 元优惠 40 元：310−40=270（元）。', 'paper', '["practice", "ykl3sx", "2.10"]', NULL, 0);

INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, images, deleted) VALUES (
 1018, '数学', '三年级', '拓展', 3, '{"stem": "奶奶钱包里有：100元4张、50元1张、20元4张、5元5张。如果不需要找零，可以怎么付款 270 元？请给出一种付款方案（填写各面额张数）。", "options": null}', '答案不唯一。如：100元2张+50元1张+20元1张=270元（表填：100→2张，50→1张，20→1张，5→0张）', '凑 270 元且不需找零：2×100+1×50+1×20=270（元）。其他组合相加等于 270 元即可。', 'paper', '["practice", "ykl3sx", "2.10"]', NULL, 0);
